//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
	"github.com/stretchr/testify/require"
)

func TestEnum_PRECISION_LAND_MODE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.PRECISION_LAND_MODE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.PRECISION_LAND_MODE_DISABLED.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.PRECISION_LAND_MODE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.PRECISION_LAND_MODE_DISABLED, dec)
	})
}
